var count = ctx.input && typeof ctx.input.count === 'number' ? ctx.input.count : 1;
var sides = ctx.input && typeof ctx.input.sides === 'number' ? ctx.input.sides : 20;
var modifier = ctx.input && typeof ctx.input.modifier === 'number' ? ctx.input.modifier : 0;

if (!Number.isInteger(count) || count < 1) {
  throw new Error('input.count must be a positive integer.');
}
if (!Number.isInteger(sides) || sides < 2) {
  throw new Error('input.sides must be an integer of at least 2.');
}
if (!Number.isInteger(modifier)) {
  throw new Error('input.modifier must be an integer.');
}

var rolls = [];
var total = modifier;
for (var i = 0; i < count; i++) {
  var roll = ctx.randomInt(1, sides);
  rolls.push(roll);
  total += roll;
}

ctx.log('rolled ' + count + 'd' + sides + (modifier ? (modifier > 0 ? '+' : '') + modifier : '') + ' = ' + total);

return {
  narration: count + 'd' + sides + (modifier ? (modifier > 0 ? '+' : '') + modifier : '') + ' rolled ' + rolls.join(', ') + ' for a total of ' + total + '.',
  effects: [],
  data: { count: count, sides: sides, modifier: modifier, rolls: rolls, total: total }
};

var statsRaw = ctx.roles.subject.components['fixture.legacy.stats'];
var lockRaw = ctx.roles.lock.components['fixture.legacy.lock'];

if (!statsRaw) {
  throw new Error(ctx.roles.subject.name + ' has no stats component for a lock-picking attempt.');
}
if (!lockRaw) {
  throw new Error(ctx.roles.lock.name + ' has no lock component.');
}

var stats = JSON.parse(statsRaw);
var lock = JSON.parse(lockRaw);
if (typeof stats.agility !== 'number') {
  throw new Error(ctx.roles.subject.name + ' needs a numeric agility value to pick a lock.');
}
if (typeof lock.difficulty !== 'number') {
  throw new Error(ctx.roles.lock.name + ' needs a numeric lock difficulty.');
}

var bonus = typeof ctx.input.bonus === 'number' ? ctx.input.bonus : 0;
var roll = ctx.randomInt(1, 20);
var total = roll + stats.agility + bonus;
var succeeded = total >= lock.difficulty;

return {
  narration: ctx.roles.subject.name + (succeeded ? ' picks the lock on ' : ' fails to pick the lock on ') +
    ctx.roles.lock.name + ' (' + total + ' against ' + lock.difficulty + ').',
  effects: [],
  data: { roll: roll, agility: stats.agility, bonus: bonus, total: total, difficulty: lock.difficulty, succeeded: succeeded }
};
